/** Minimal Web MIDI typings (the full lib.dom types are not enabled in this project). */
declare namespace WebMidi {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  type MIDIInput = any;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  type MIDIAccess = any;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  type MIDIMessageEvent = any;
}
